**What this code covers**

- Collects .load() calls in the current tick, then dispatches them as a single batched fetch.
- Parses a subset of GraphQL: user(id:42){ name posts{ title author{ name } } }
- Parses a comma- or newline-separated list of field selections with optional nested {...}.
- Resolve each field selection on parent (an object of type_name).
- Minimal GraphQL server in pure Python: schema, parser, resolvers,
- DataLoader batching, query execution. Educational; no external deps.
- Toy data store (in-memory)
- Track DB query count so we can demonstrate DataLoader batching.

**Defines:** `db_get_user()`, `db_get_posts_by_user()`, `db_get_users_by_ids()`, `DataLoader`, `Field`, `Schema`, `Selection`, `parse_query()`, `_parse_selections()`, `resolve_user()`

```python
# Minimal GraphQL server in pure Python: schema, parser, resolvers,
# DataLoader batching, query execution. Educational; no external deps.

import json
import re
from dataclasses import dataclass, field
from typing import Any, Callable, Optional
from collections import defaultdict
import threading

# --- Toy data store (in-memory) -----------------------------------

USERS = {
    1: {"id": 1, "name": "Ada Lovelace", "email": "ada@example.com",
        "role": "admin"},
    2: {"id": 2, "name": "Grace Hopper", "email": "grace@example.com",
        "role": "engineer"},
    3: {"id": 3, "name": "Alan Turing", "email": "alan@example.com",
        "role": "engineer"},
}
POSTS = {
    101: {"id": 101, "title": "Analytical Engine Notes",
          "author_id": 1, "views": 5000},
    102: {"id": 102, "title": "First Compiler", "author_id": 2,
          "views": 3000},
    103: {"id": 103, "title": "COBOL Design", "author_id": 2,
          "views": 8000},
    104: {"id": 104, "title": "Turing Machine", "author_id": 3,
          "views": 12000},
}

# Track DB query count so we can demonstrate DataLoader batching.
DB_QUERY_LOG = []

def db_get_user(uid: int) -> Optional[dict]:
    DB_QUERY_LOG.append(("users", uid))
    return USERS.get(uid)

def db_get_posts_by_user(uid: int) -> list:
    DB_QUERY_LOG.append(("posts_by_user", uid))
    return [p for p in POSTS.values() if p["author_id"] == uid]

def db_get_users_by_ids(ids: list) -> list:
    # ONE batched query -- the whole point of DataLoader.
    DB_QUERY_LOG.append(("users_batch", tuple(sorted(ids))))
    return [USERS[i] for i in ids if i in USERS]

# --- DataLoader (batches all loads in a single event-loop tick) ---

class DataLoader:
    """Collects .load() calls in the current tick, then dispatches them
    as a single batched fetch. Returns the cached value if available,
    else queues the key and returns None -- the executor does two
    passes so the second pass sees the populated cache."""

    def __init__(self, batch_fn: Callable[[list], list]):
        self._batch_fn = batch_fn
        self._queue = []  # keys not yet fetched
        self._cache = {}  # key -> value, populated after dispatch

    def load(self, key) -> Any:
        if key in self._cache:
            return self._cache[key]
        # Not cached yet: queue for batch fetch (dedupe).
        if key not in self._queue:
            self._queue.append(key)
        return None  # caller re-resolves after dispatch()

    def dispatch(self):
        if not self._queue:
            return
        keys = list(self._queue)
        values = self._batch_fn(keys)
        for k, v in zip(keys, values):
            self._cache[k] = v
        self._queue.clear()

    def reset(self):
        self._queue.clear()
        self._cache.clear()

# --- Schema (declared as Python dataclasses) ----------------------

@dataclass
class Field:
    name: str
    resolver: Callable
    args: dict = field(default_factory=dict)

@dataclass
class Schema:
    query_fields: dict  # name -> Field

# --- Tiny GraphQL query parser (handles a useful subset) ----------

@dataclass
class Selection:
    name: str
    args: dict
    selections: list  # nested Selections

def parse_query(query: str) -> Selection:
    """Parses a subset of GraphQL: `user(id:42){ name posts{ title author{ name } } }`"""
    # Strip "query" keyword and braces.
    q = query.strip()
    if q.startswith("query"):
        q = q[len("query"):].strip()
    # Match top-level: name(args) { selections }
    m = re.match(r"(\w+)\s*(?:\(([^)]*)\))?\s*\{(.*)\}\s*$", q, re.DOTALL)
    if not m:
        raise ValueError(f"cannot parse query: {query!r}")
    name, args_str, body = m.group(1), m.group(2), m.group(3)
    args = {}
    if args_str:
        for kv in args_str.split(","):
            k, v = kv.strip().split(":")
            v = v.strip().strip('"')
            try:
                v = int(v)
            except ValueError:
                pass
            args[k.strip()] = v
    return Selection(name=name, args=args,
                     selections=_parse_selections(body.strip()))

def _parse_selections(body: str) -> list:
    """Parses a comma- or newline-separated list of field selections
    with optional nested `{...}`."""
    sels = []
    i = 0
    while i < len(body):
        # skip whitespace and commas
        while i < len(body) and body[i] in " \n\t,":
            i += 1
        if i >= len(body):
            break
        # read field name
        m = re.match(r"\w+", body[i:])
        if not m:
            break
        name = m.group()
        i += len(name)
        # optional args
        args = {}
        if i < len(body) and body[i] == "(":
            end = body.index(")", i)
            for kv in body[i + 1:end].split(","):
                k, v = kv.strip().split(":")
                v = v.strip().strip('"')
                try:
                    v = int(v)
                except ValueError:
                    pass
                args[k.strip()] = v
            i = end + 1
        # skip whitespace before optional nested selections
        while i < len(body) and body[i] in " \n\t":
            i += 1
        # optional nested selections
        nested = []
        if i < len(body) and body[i] == "{":
            depth = 1
            j = i + 1
            while j < len(body) and depth > 0:
                if body[j] == "{":
                    depth += 1
                elif body[j] == "}":
                    depth -= 1
                j += 1
            nested = _parse_selections(body[i + 1:j - 1])
            i = j
        sels.append(Selection(name=name, args=args, selections=nested))
    return sels

# --- Resolvers ----------------------------------------------------

# A DataLoader for batched author fetches (created per-request).
author_loader = DataLoader(lambda ids: db_get_users_by_ids(ids))

def resolve_user(parent, args, context, info):
    return db_get_user(args["id"])

def resolve_user_name(parent, args, context, info):
    return parent["name"]

def resolve_user_email(parent, args, context, info):
    return parent["email"]

def resolve_user_role(parent, args, context, info):
    return parent["role"]

def resolve_user_posts(parent, args, context, info):
    return db_get_posts_by_user(parent["id"])

def resolve_post_title(parent, args, context, info):
    return parent["title"]

def resolve_post_views(parent, args, context, info):
    return parent["views"]

def resolve_post_author(parent, args, context, info):
    # THIS is the magic: instead of db_get_user(parent['author_id']),
    # we call author_loader.load() which batches all calls in this tick.
    placeholder = author_loader.load(parent["author_id"])
    return placeholder  # resolved after dispatch()

SCHEMA = Schema(query_fields={
    "user": Field(name="user", resolver=resolve_user),
})

def resolve_field(type_name, field_name, parent, args, context, info):
    table = {
        ("User", "name"): resolve_user_name,
        ("User", "email"): resolve_user_email,
        ("User", "role"): resolve_user_role,
        ("User", "posts"): resolve_user_posts,
        ("Post", "title"): resolve_post_title,
        ("Post", "views"): resolve_post_views,
        ("Post", "author"): resolve_post_author,
    }
    fn = table.get((type_name, field_name))
    if fn is None:
        raise ValueError(f"no resolver for {type_name}.{field_name}")
    return fn(parent, args, context, info)

# --- Executor -----------------------------------------------------

# Maps (parent_type, field_name) -> child_type for nested selections.
CHILD_TYPE = {
    ("User", "posts"): "Post",
    ("Post", "author"): "User",
}

def execute(query: str, context: dict = None) -> dict:
    DB_QUERY_LOG.clear()
    author_loader.reset()
    sel = parse_query(query)
    field = SCHEMA.query_fields.get(sel.name)
    if field is None:
        return {"errors": [{"message":
                f"unknown query field: {sel.name}"}]}
    # Pass 1: resolve the top-level field (e.g., Query.user) to get the
    # root object, then resolve nested selections. DataLoader queues
    # author IDs during this pass but returns None for uncached entries.
    root = field.resolver(None, sel.args, context, None)
    _resolve_object(root, sel.selections, "User", context)
    # Dispatch DataLoader: one batched DB query for all queued author IDs.
    author_loader.dispatch()
    # Pass 2: re-resolve; author cache is now populated.
    result = _resolve_object(root, sel.selections, "User", context)
    return {"data": result, "db_queries": list(DB_QUERY_LOG)}

def _resolve_object(parent, selections, type_name, context):
    """Resolve each field selection on `parent` (an object of `type_name`)."""
    if parent is None:
        return None
    out = {}
    for sel in selections:
        value = resolve_field(type_name, sel.name, parent, sel.args,
                              context, None)
        if not sel.selections:
            # Leaf field (string, int, etc.) -- emit directly.
            out[sel.name] = value
            continue
        # Nested object field -- recurse.
        if value is None:
            out[sel.name] = None
            continue
        child_type = CHILD_TYPE.get((type_name, sel.name), "User")
        if isinstance(value, list):
            out[sel.name] = [_resolve_object(item, sel.selections,
                                             child_type, context)
                             for item in value]
        else:
            out[sel.name] = _resolve_object(value, sel.selections,
                                            child_type, context)
    return out

def run_demo():
    print("=== GraphQL demo ===\n")

    # Without DataLoader (simulate naive N+1): resolve each author directly.
    print("--- Naive N+1 (each Post.author issues its own DB query) ---")
    naive_log = []
    for post in [POSTS[101], POSTS[102], POSTS[103], POSTS[104]]:
        u = db_get_user(post["author_id"])
        naive_log.append((post["id"], u["name"] if u else None))
    print(f"  4 posts -> 4 separate DB queries: {naive_log}")
    print(f"  total DB queries: {len(DB_QUERY_LOG)} (1 for posts + 4 for "
          f"authors = N+1)")

    print("\n--- With DataLoader (batched) ---")
    DB_QUERY_LOG.clear()
    query = 'user(id:2){ name role posts { title views author { name } } }'
    result = execute(query)
    print(f"  query: {query}")
    print(f"  response: {json.dumps(result['data'], indent=2)}")
    print(f"  DB queries issued: {len(result['db_queries'])}")
    for q in result["db_queries"]:
        print(f"    - {q}")
    print(f"  note: posts by user 2 have author_id=2, so DataLoader "
          f"collapses them into 1 batched query (not 2 separate).")

    print("\n--- Demonstrating field selection (no over-fetching) ---")
    DB_QUERY_LOG.clear()
    query2 = 'user(id:1){ name }'
    result2 = execute(query2)
    print(f"  query: {query2}")
    print(f"  response: {json.dumps(result2['data'])}")
    print(f"  note: client asked only for 'name'; email/role/posts were "
          f"NOT fetched (no over-fetching).")

if __name__ == "__main__":
    run_demo()
```
